pub struct Widget {
    pub label: String,
}

/// Build the widget the toolbar shows.
pub fn build_widget(label: &str) -> Widget {
    Widget { label: label.to_string() }
}

pub fn render(w: &Widget) -> String {
    format!("[{}]", w.label)
}

